      "arFull": "اِنَّمَا یَعْمُرُ مَسٰجِدَ اللّٰهِ مَنْ اٰمَنَ بِاللّٰهِ وَالْیَوْمِ الْاٰخِرِ وَاَقَامَ الصَّلٰوةَ وَاٰتَی الزَّكٰوةَ وَلَمْ یَخْشَ اِلَّا اللّٰهَ فَعَسٰۤی اُولٰٓىِٕكَ اَنْ یَّكُوْنُوْا مِنَ الْمُهْتَدِیْنَ ۟",
