      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا تَتَّخِذُوْۤا اٰبَآءَكُمْ وَاِخْوَانَكُمْ اَوْلِیَآءَ اِنِ اسْتَحَبُّوا الْكُفْرَ عَلَی الْاِیْمَانِ ؕ وَمَنْ یَّتَوَلَّهُمْ مِّنْكُمْ فَاُولٰٓىِٕكَ هُمُ الظّٰلِمُوْنَ ۟",
