      "arFull": "اِتَّخَذُوْۤا اَحْبَارَهُمْ وَرُهْبَانَهُمْ اَرْبَابًا مِّنْ دُوْنِ اللّٰهِ وَالْمَسِیْحَ ابْنَ مَرْیَمَ ۚ وَمَاۤ اُمِرُوْۤا اِلَّا لِیَعْبُدُوْۤا اِلٰهًا وَّاحِدًا ۚ لَاۤ اِلٰهَ اِلَّا هُوَ ؕ سُبْحٰنَهٗ عَمَّا یُشْرِكُوْنَ ۟",
