      "arFull": "هُوَ الَّذِیْۤ اَرْسَلَ رَسُوْلَهٗ بِالْهُدٰی وَدِیْنِ الْحَقِّ لِیُظْهِرَهٗ عَلَی الدِّیْنِ كُلِّهٖ ۙ وَلَوْ كَرِهَ الْمُشْرِكُوْنَ ۟",
