      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْۤا اِنَّ كَثِیْرًا مِّنَ الْاَحْبَارِ وَالرُّهْبَانِ لَیَاْكُلُوْنَ اَمْوَالَ النَّاسِ بِالْبَاطِلِ وَیَصُدُّوْنَ عَنْ سَبِیْلِ اللّٰهِ ؕ وَالَّذِیْنَ یَكْنِزُوْنَ الذَّهَبَ وَالْفِضَّةَ وَلَا یُنْفِقُوْنَهَا فِیْ سَبِیْلِ اللّٰهِ ۙ فَبَشِّرْهُمْ بِعَذَابٍ اَلِیْمٍ ۟ۙ",
      "ur": "اے ایمان والو! اکثر علما اور عابد، لوگوں کا مال ناحق کھا جاتے ہیں اور اللہ کی راه سے روک دیتے ہیں[1] اور جو لوگ سونے چاندی کا خزانہ رکھتے ہیں اور اللہ کی راه میں خرچ نہیں کرتے، انہیں دردناک عذاب کی خبر پہنچا دیجئے۔[2]",
      "en": "O you who have believed, indeed many of the scholars and the monks devour the wealth of people unjustly[469] and avert [them] from the way of Allāh. And those who hoard gold and silver and spend it not in the way of Allāh - give them tidings of a painful punishment.",
