      "arFull": "اِنَّمَا النَّسِیْٓءُ زِیَادَةٌ فِی الْكُفْرِ یُضَلُّ بِهِ الَّذِیْنَ كَفَرُوْا یُحِلُّوْنَهٗ عَامًا وَّیُحَرِّمُوْنَهٗ عَامًا لِّیُوَاطِـُٔوْا عِدَّةَ مَا حَرَّمَ اللّٰهُ فَیُحِلُّوْا مَا حَرَّمَ اللّٰهُ ؕ زُیِّنَ لَهُمْ سُوْٓءُ اَعْمَالِهِمْ ؕ وَاللّٰهُ لَا یَهْدِی الْقَوْمَ الْكٰفِرِیْنَ ۟۠",
