      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا مَا لَكُمْ اِذَا قِیْلَ لَكُمُ انْفِرُوْا فِیْ سَبِیْلِ اللّٰهِ اثَّاقَلْتُمْ اِلَی الْاَرْضِ ؕ اَرَضِیْتُمْ بِالْحَیٰوةِ الدُّنْیَا مِنَ الْاٰخِرَةِ ۚ فَمَا مَتَاعُ الْحَیٰوةِ الدُّنْیَا فِی الْاٰخِرَةِ اِلَّا قَلِیْلٌ ۟",
