      "arFull": "لَا یَسْتَاْذِنُكَ الَّذِیْنَ یُؤْمِنُوْنَ بِاللّٰهِ وَالْیَوْمِ الْاٰخِرِ اَنْ یُّجَاهِدُوْا بِاَمْوَالِهِمْ وَاَنْفُسِهِمْ ؕ وَاللّٰهُ عَلِیْمٌۢ بِالْمُتَّقِیْنَ ۟",
