      "arFull": "وَمِنْهُمْ مَّنْ یَّقُوْلُ ائْذَنْ لِّیْ وَلَا تَفْتِنِّیْ ؕ اَلَا فِی الْفِتْنَةِ سَقَطُوْا ؕ وَاِنَّ جَهَنَّمَ لَمُحِیْطَةٌ بِالْكٰفِرِیْنَ ۟",
