      "number": 74,
      "arFull": "یَحْلِفُوْنَ بِاللّٰهِ مَا قَالُوْا ؕ وَلَقَدْ قَالُوْا كَلِمَةَ الْكُفْرِ وَكَفَرُوْا بَعْدَ اِسْلَامِهِمْ وَهَمُّوْا بِمَا لَمْ یَنَالُوْا ۚ وَمَا نَقَمُوْۤا اِلَّاۤ اَنْ اَغْنٰىهُمُ اللّٰهُ وَرَسُوْلُهٗ مِنْ فَضْلِهٖ ۚ فَاِنْ یَّتُوْبُوْا یَكُ خَیْرًا لَّهُمْ ۚ وَاِنْ یَّتَوَلَّوْا یُعَذِّبْهُمُ اللّٰهُ عَذَابًا اَلِیْمًا ۙ فِی الدُّنْیَا وَالْاٰخِرَةِ ۚ وَمَا لَهُمْ فِی الْاَرْضِ مِنْ وَّلِیٍّ وَّلَا نَصِیْرٍ ۟",
