      "number": 91,
      "arFull": "لَیْسَ عَلَی الضُّعَفَآءِ وَلَا عَلَی الْمَرْضٰی وَلَا عَلَی الَّذِیْنَ لَا یَجِدُوْنَ مَا یُنْفِقُوْنَ حَرَجٌ اِذَا نَصَحُوْا لِلّٰهِ وَرَسُوْلِهٖ ؕ مَا عَلَی الْمُحْسِنِیْنَ مِنْ سَبِیْلٍ ؕ وَاللّٰهُ غَفُوْرٌ رَّحِیْمٌ ۟ۙ",
