      "arFull": "سَیَحْلِفُوْنَ بِاللّٰهِ لَكُمْ اِذَا انْقَلَبْتُمْ اِلَیْهِمْ لِتُعْرِضُوْا عَنْهُمْ ؕ فَاَعْرِضُوْا عَنْهُمْ ؕ اِنَّهُمْ رِجْسٌ ؗ وَّمَاْوٰىهُمْ جَهَنَّمُ ۚ جَزَآءً بِمَا كَانُوْا یَكْسِبُوْنَ ۟",
