      "arFull": "وَقُلِ اعْمَلُوْا فَسَیَرَی اللّٰهُ عَمَلَكُمْ وَرَسُوْلُهٗ وَالْمُؤْمِنُوْنَ ؕ وَسَتُرَدُّوْنَ اِلٰی عٰلِمِ الْغَیْبِ وَالشَّهَادَةِ فَیُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُوْنَ ۟ۚ",
