      "arFull": "اَفَمَنْ اَسَّسَ بُنْیَانَهٗ عَلٰی تَقْوٰی مِنَ اللّٰهِ وَرِضْوَانٍ خَیْرٌ اَمْ مَّنْ اَسَّسَ بُنْیَانَهٗ عَلٰی شَفَا جُرُفٍ هَارٍ فَانْهَارَ بِهٖ فِیْ نَارِ جَهَنَّمَ ؕ وَاللّٰهُ لَا یَهْدِی الْقَوْمَ الظّٰلِمِیْنَ ۟",
      "ur": "پھر آیا ایسا شخص بہتر ہے جس نے اپنی عمارت کی بنیاد اللہ سے ڈرنے پر اور اللہ کی خوشنودی پر رکھی ہو، یا وه شخص، کہ جس نے اپنی عمارت کی بنیاد کسی گھاٹی کے کنارے پر جو کہ گرنے ہی کو ہو، رکھی ہو، پھر وه اس کو لے کر آتش دوزخ میں گر پڑے[1] ، اور اللہ تعالیٰ ایسے ﻇالموں کو سمجھ ہی نہیں دیتا۔",
