      "arFull": "لَقَدْ تَّابَ اللّٰهُ عَلَی النَّبِیِّ وَالْمُهٰجِرِیْنَ وَالْاَنْصَارِ الَّذِیْنَ اتَّبَعُوْهُ فِیْ سَاعَةِ الْعُسْرَةِ مِنْ بَعْدِ مَا كَادَ یَزِیْغُ قُلُوْبُ فَرِیْقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَیْهِمْ ؕ اِنَّهٗ بِهِمْ رَءُوْفٌ رَّحِیْمٌ ۟ۙ",
