      "arFull": "وَّعَلَی الثَّلٰثَةِ الَّذِیْنَ خُلِّفُوْا ؕ حَتّٰۤی اِذَا ضَاقَتْ عَلَیْهِمُ الْاَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَیْهِمْ اَنْفُسُهُمْ وَظَنُّوْۤا اَنْ لَّا مَلْجَاَ مِنَ اللّٰهِ اِلَّاۤ اِلَیْهِ ؕ ثُمَّ تَابَ عَلَیْهِمْ لِیَتُوْبُوْا ؕ اِنَّ اللّٰهَ هُوَ التَّوَّابُ الرَّحِیْمُ ۟۠",
